import{_ as a,o as n,c as p,a6 as e}from"./chunks/framework.De615z8S.js";const m=JSON.parse('{"title":"日文本地化：术语、换行与事实复核","description":"","frontmatter":{"id":"P17","title":"日文本地化：术语、换行与事实复核","chapter":"13","topic":"cross-border","status":"已公开","evidence_status":"完整模板，尚未执行图像任务或流程验证","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["cross-border-knowledge"],"order":117},"headers":[],"relativePath":"prompts/P17.md","filePath":"prompts/P17.md"}'),l={name:"prompts/P17.md"};function t(i,s,c,o,r,d){return n(),p("div",null,[...s[0]||(s[0]=[e(`<h1 id="p17-日文本地化-术语、换行与事实复核" tabindex="-1">P17 日文本地化：术语、换行与事实复核 <a class="header-anchor" href="#p17-日文本地化-术语、换行与事实复核" aria-label="Permalink to &quot;P17 日文本地化：术语、换行与事实复核&quot;">​</a></h1><p>类型：文案本地化。替换项目：商品事实、目标日本市场、准确中文与位置。下面提供完整填写示范，虚构商品DN01只作练习；正式使用时替换事实与素材。示范未附照片、未执行任务。</p><p><a href="./../ecommerce/localization">逐步教程</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把商品事实整理成日文图片标签和商品说明草稿，本次不生成图像。</span></span>
<span class="line"><span>以下DN01／DeskNest是虚构练习数据，不代表实际品牌或商品；正式任务必须换成已核实的商品记录。</span></span>
<span class="line"><span>练习事实：带盖桌面收纳盒；白色ABS；外尺寸长220×宽150×高120 mm；可拆隔板1个。</span></span>
<span class="line"><span>发货内容：盒体1、盖子1、隔板1。文具等场景道具不随商品发货。</span></span>
<span class="line"><span>容积、耐温、承重、防水、食品接触、认证和回收属性均未知，不补相关声明。</span></span>
<span class="line"><span>图片输入如有：图1是真实商品外观依据；图2是实际细节；图3仅参考背景和构图，不使用其商品、Logo或参数。</span></span>
<span class="line"><span>未附实拍时先给素材清单和可执行方案；不要臆画正式商品或未拍摄结构。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>目标是日本市场商品副图和详情文字；没有指定具体平台时，平台参数写待核。</span></span>
<span class="line"><span>获准术语示范：ふた付きデスク収納ボックス；取り外し可能な仕切り；外寸：長さ220 × 幅150 × 高さ120 mm；本体1点、ふた1点、仕切り1点。</span></span>
<span class="line"><span>请核对这些术语与本次实际商品是否吻合，再给3个短标签和一段简短说明；不要添加耐熱、防水、食品用等未知事实。</span></span>
<span class="line"><span>分别输出：中文母表、日文草稿、中文回译、数值／单位／配件对照、可能歧义和适合手机的换行建议。</span></span>
<span class="line"><span>长宽高标签不交换；原包装文字不擅改成不存在的日文包装版本。</span></span>
<span class="line"><span>文字后期排版保留可编辑层，不使用整图模型反复改写小字；生成后的日文逐字对照确认。</span></span>
<span class="line"><span>草稿未由熟悉目标语言与类目的人复核时，标为待复核，不写已经审定。</span></span>
<span class="line"><span>本次范围按上述任务执行；没有图像能力时只交方案并写明状态。</span></span>
<span class="line"><span>实际执行时保留真实商品层与准确文字，逐项核对形状、颜色、盖子、隔板、配件、单位和文字。</span></span>
<span class="line"><span>目标尺寸与工具实际输出分别报告；不把画质形容词、计划路径或未创建的PSD当作已交付结果。</span></span>
<span class="line"><span>最终列：已完成、需要补的素材、无法确认的项目、实际存在的文件与下一步。</span></span></code></pre></div><p>检查：输入角色清楚、事实与未知分开、输出范围明确，实际文件与后台状态据实记录。</p>`,5)])])}const h=a(l,[["render",t]]);export{m as __pageData,h as default};
